465	  continueCurrent(): WorkflowEffect {
466	    if (!this.active) return { kind: "idle", phase: this.phase };
467	    return {
468	      kind: "advanced",
469	      phase: this.phase,
470	      step: this.PHASE_STEP[this.phase],
471	      prompt: this.promptFor(this.phase),
472	      entry: this.entryFor(this.phase, false),
473	      footer: this.footerFor(),
474	    };
475	  }

