720	        const d = result.details as { closed?: boolean; artifactDir?: string };
721	        if (!d.closed) {
722	          return new Text(theme.fg("dim", "○ no workflow to end"), 0, 0);
723	        }
724	        return new Text(
725	          theme.fg("success", `✓ ${footerLabel} closed · ${d.artifactDir}`),
726	          0,
727	          0,
728	        );
729	      },
730	    } satisfies ToolDefinition);
731	
732	    // ── session_start: disk state is never auto-attached. A session entry is
733	    // merely a convenience pointer for rendering a stale-but-useful footer. ──
734	    pi.on("session_start", async (_event: any, ctx: ExtensionContext) => {
735	      const entries = ctx.sessionManager.getEntries();
736	      for (let i = entries.length - 1; i >= 0; i--) {
737	        const data = (entries[i] as { type: string; customType?: string; data?: any }).data;
738	        if (!data || data.mode !== mode || typeof data.workflowStatePath !== "string") continue;
739	        try {
740	          const run = await loadWorkflowRun(data.workflowStatePath, modesFor(config));
741	          if (run.status === "active") {
742	            ctx.ui.setStatus(config.statusKey, ctx.ui.theme.fg(
743	              "warning",
744	              `● ${config.footerLabel} · ${config.phases.indexOf(run.phase) + 1}/${config.phases.length} ${run.phase} (resume required)`,
745	            ));
746	          }
747	        } catch {
748	          // Old/custom entries are intentionally non-authoritative.
749	        }
750	        break;
751	      }
752	    });
753	
754	    // ── tool_call: enforce workflow boundaries. ──
755	    pi.on("tool_call", (event: any, _ctx: ExtensionContext) => {
885	        const agent = event.input?.agent;
886	
887	        if (agent === "builder") {
888	          // Build step done → drive the commentator review.
889	          ls.stage = "reviewing";
890	          loopPrompt = `Builder finished. Call the subagent tool now with { agent: "commentator", task: "..." } to review the builder's uncommitted diff against ${dir}/plan.md. Craft the review task yourself based on what matters for this task. End the review with exactly one line on its own:
891	  WORKFLOW_REVIEW_STATUS: clean
892	or
893	  WORKFLOW_REVIEW_STATUS: blocking`; 
894	        } else if (agent === "commentator") {
895	          ls.reviewRound += 1;
896	          const reviewText = textFromToolResultContent(event.content);
897	          if (reviewText) {
898	            const reviewPath = `loop-review-${ls.reviewRound}.md`;
899	            await mkdir(dir, { recursive: true });
900	            await writeFile(resolve(dir, reviewPath), reviewText, "utf8");
901	            ls.reviewPath = reviewPath;
902	          }
903	          const status = parseLoopReviewStatus(reviewText);
904	          if (status === "clean") {
905	            ls.stage = "clean";
906	            await mkdir(dir, { recursive: true });
907	            await writeFile(resolve(dir, config.phaseArtifacts["loop"]!), `Loop complete after ${ls.reviewRound} review round(s).\n${MARKERS.loopComplete}`, "utf8");
908	            // onArtifactMaybe below sees loop-complete.md and advances to audit.
909	          } else if (ls.reviewRound >= ls.maxIterations) {
910	            // Cap reached without a clean review. Notify once, stop driving.
911	            const wasMaxed = ls.stage === "maxed";
912	            ls.stage = "maxed";
913	            if (!wasMaxed) {
914	              ctx.ui.notify(
915	                `Workflow loop hit max iterations (${ls.maxIterations}) without a clean review. Last review status: ${status ?? "no marker"}. Resolve issues manually or re-run.`,
916	                "warning",
917	              );
918	            }
919	            // A genuine clean review on a later round still advances — the
920	            // clean branch above runs first.
921	          } else {
922	            // Blocking (or no marker) → drive a builder fix round.
923	            ls.stage = "building";
924	            const reason = status === "blocking"
925	              ? "the blocking issues listed in the review"
926	              : "the review (no WORKFLOW_REVIEW_STATUS: clean|blocking marker was found)";
927	            loopPrompt = `Review round ${ls.reviewRound} was blocking. Call the subagent tool now with { agent: "builder", task: "..." } to fix ${reason}. Give the builder the feedback in ${dir}/${ls.reviewPath ?? `loop-review-${ls.reviewRound}.md`} and the relevant artifact paths. After the builder returns, the workflow will drive the next review automatically.`;
928	          }
929	        }
930	        // Non-builder/commentator subagent calls in loop fall through to
931	        // onArtifactMaybe (a no-op unless loop-complete.md exists).
932	      }
933	      const eff = await sm.onArtifactMaybe(deps);
934	      // Clear loop state once we have left the loop phase (advanced to audit).
935	      if (sm.snapshot.phase !== "loop") {
936	        controller.loopState = undefined;
937	      }
938	      try {
939	        await persistAfter(controller, eventBefore);
940	      } catch (error) {
941	        ctx.ui.notify(`Workflow state was not saved: ${error instanceof Error ? error.message : String(error)}`, "warning");
942	        return;
943	      }
944	      applyControllerEffect(controller, ctx, eff);
945	      if (loopPrompt && sm.snapshot.active) continueAgent(pi, ctx, loopPrompt);
946	    });
947	
948	    // ── /<command> ──
949	    pi.registerCommand(options.commandName, {
950	      description: options.commandDescription,
425	  }
426	
427	  // ponytail: the tool_result auto-advance hook. One call, one apply.
428	  // Reentrancy guard + autoArmed + artifact gate all live in here — the
429	  // adapter's hook is `const eff = await sm.onArtifactMaybe(deps); apply(...)`.
430	  async onArtifactMaybe(deps: WorkflowDeps): Promise<WorkflowEffect> {
431	    if (this.advancing) return { kind: "noOp" };
432	    if (!this.active || !this.autoArmed) return { kind: "noOp" };
433	    const expected = this.config.phaseArtifacts[this.phase];
434	    if (!expected) return { kind: "noOp" };
435	    // Acquire synchronously before any await so a concurrent call sees advancing=true.
436	    this.advancing = true;
437	    try {
438	      // ponytail: Plan 4 — distinguish "not yet written" (keep waiting, noOp)
439	      // from "written but semantically invalid" (block + surface reason so the
440	      // model learns which marker is missing instead of stalling silently).
441	      const sat = await this.artifactSatisfiedFor(this.phase, deps);
442	      if (!sat.exists) return { kind: "noOp" };
443	      if (sat.reason) {
444	        // Keep armed: the artifact exists but failed the semantic gate. The
445	        // next corrected write/subagent result must be able to advance this
446	        // same phase; disarming here leaves the workflow stuck forever.
447	        const missing = this.config.phaseArtifacts[this.phase]!;
448	        return { kind: "blocked", phase: this.phase, missing, reason: sat.reason };
449	      }
450	      this.autoArmed = false;
451	      const out = await this.advancePhase(deps, true);
452	      if (out.kind === "terminalNeedsArtifacts") {
453	        // Keep listening: audit/review may land in separate writes.
454	        this.autoArmed = true;
455	      }
456	      return out;
457	    } finally {
458	      this.advancing = false;
459	    }
460	  }
461	
462	  // ponytail: /<command> "continue current workflow" — re-emit the current
463	  // phase prompt without advancing. Fixes Design A's rehydrate regression:
464	  // no adapter caching; the prompt is recomputed from config on demand.
465	  continueCurrent(): WorkflowEffect {
466	    if (!this.active) return { kind: "idle", phase: this.phase };
467	    return {
468	      kind: "advanced",
469	      phase: this.phase,
470	      step: this.PHASE_STEP[this.phase],
471	      prompt: this.promptFor(this.phase),
472	      entry: this.entryFor(this.phase, false),
473	      footer: this.footerFor(),
474	    };
475	  }

